from flask import Flask, Blueprint

# Create main Flask application
app = Flask(__name__)

# Create users blueprint as a modular component
users_bp = Blueprint('users', __name__)

@users_bp.route('/')
def users_list():
    return {'message': 'Users list', 'users': ['Alice', 'Bob', 'Charlie']}

@users_bp.route('/<int:user_id>')
def get_user(user_id):
    return {'message': f'User {user_id}', 'id': user_id}

@users_bp.route('/<int:user_id>/profile')
def user_profile(user_id):
    return {'message': f'Profile for user {user_id}', 'id': user_id}

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    return {'message': f'Updated user {user_id}', 'id': user_id}

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    return {'message': f'Deleted user {user_id}', 'id': user_id}

# Register the blueprint under /users prefix
app.register_blueprint(users_bp, url_prefix='/users')

# Main route
@app.route('/')
def home():
    return {'message': 'Welcome to Flask app', 'endpoints': {
        'users': '/users',
        'user_detail': '/users/<id>',
        'user_profile': '/users/<id>/profile'
    }}

if __name__ == '__main__':
    app.run(debug=True, port=5000)

